#include <stdio.h>

#define MAX_ROWS 20
#define MAX_COLS 20

int main()
{
	// 输入获取
	int m, n;
	scanf("%d %d", &m, &n);

	int matrix[MAX_ROWS][MAX_COLS];
	for(int i = 0; i < m; i++) {
		for(int j = 0; j < n; j++) {
			scanf("%d", &matrix[i][j]);
		}
	}

	// 记录需要打开的监控器数量
	int count = 0;

	// 上下左右四个方向的偏移量
	int offsets[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

	for(int x = 0; x < m; x++) {
		for(int y = 0; y < n; y++) {
			// 如果元素值为1，对应位置的监控器就要打开
			if(matrix[x][y] == 1) {
				count++;
				continue;
			}

			// 如果元素值为0，则需要进一步检查其上下左右4个位置，只要这四个位置有一个元素值为1，则当前位置的监控器需要打开
			for(int i = 0; i < 4; i++) {
				int offsetX = offsets[i][0];
				int offsetY = offsets[i][1];

				int newX = x + offsetX;
				int newY = y + offsetY;

				if(newX >=0 && newX < m && newY >= 0 && newY < n && matrix[newX][newY] == 1) {
					count++;
					break;
				}
			}
		}
	}

	// 输出打印
	printf("%d\n", count);

	return 0;
}
